-- Migration 112: West Creek Skills Area, and corrections to migration 111.
-- The Metroparks trailhead sign (photographed 2026-10-31) places the Skills Area on the west
-- strand of a small loop on the east side of Satellite Loop. OSM (ODbL 1.0) way 1551207728 is
-- that loop, tagged Satellite Loop, so the west strand moves to its own POI.
-- Mileages are the sign's. Each UPDATE is guarded by the value migration 111 set, so it fires once.

INSERT INTO pois (name, brief_description, poi_roles, latitude, longitude, primary_activities, surface, difficulty, length_miles, property_owner, geometry, more_info_link)
SELECT 'West Creek Skills Area', 'A small mountain bike skills area on the east side of West Creek Satellite Loop, next to the parking lot west of High Point Park. Metroparks says the West Creek system has jumps or drop features with options to ride around them.', ARRAY['trail'], 41.384011, -81.706736, 'Biking', 'Dirt', 'Moderate', 0.1, 'Cleveland Metroparks',
  '{"type":"MultiLineString","coordinates":[[[-81.706366,41.383282],[-81.706439,41.383454],[-81.70652,41.38358],[-81.706564,41.383615],[-81.706727,41.383858],[-81.706745,41.383938],[-81.706744,41.383983],[-81.706736,41.384011],[-81.706716,41.384042],[-81.706693,41.384058],[-81.706665,41.384063],[-81.706524,41.384057],[-81.706413,41.384078],[-81.706335,41.38411]]]}'::jsonb,
  'https://www.clevelandmetroparks.com/parks/visit/activities/mountain-biking'
WHERE NOT EXISTS (SELECT 1 FROM pois WHERE name = 'West Creek Skills Area');

